-- mod-world-randomizer: player base stats for Randomizer.Stats.Era.
-- era 1 = Vanilla, from the vMaNGOS world database (world_full_14_june_2021, player_levelstats / player_classlevelstats).
-- era 2 = TBC, from cMaNGOS mangos-tbc (sql/base/mangos.sql, player_levelstats / player_classlevelstats).
-- Wrath uses AzerothCore's own player_class_stats / player_race_stats, so it has no rows here.
-- Races / classes an era lacks (Blood Elf and Draenei in Vanilla, Death Knight in both) are filled in by the module.
DELETE FROM `world_randomizer_levelstats` WHERE `era` IN (1, 2);
DELETE FROM `world_randomizer_classlevelstats` WHERE `era` IN (1, 2);
